package net.farmingtales.ftboss.boss.ai;

import java.util.*;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.*;

public final class NativeBeamComboInstaller implements Opcodes {
    private static final String ROOT="net/farmingtales/ftboss/",BOSS=ROOT+"entity/EasterBossEntity",LEVEL="net/minecraft/server/level/ServerLevel",LIVING="net/minecraft/world/entity/LivingEntity";
    private static final String DESC="(L"+LEVEL+";L"+LIVING+";)V";
    private static final Map<String,String> PREIMAGES=Map.of("beamStrike","55b499c9469aed5bf6b79e9ed7e633086873e382df2d202d9f236bf47c7a0d25","skillBeamCombo","71ed8a88cf38d748785aa5270becf43ccc95b6b8f7db34448d79832819d66757");
    private NativeBeamComboInstaller(){}
    private static void require(boolean value,String reason){if(!value)throw new IllegalStateException(reason);}
    private static MethodNode method(ClassNode owner,String name){require(owner.name.equals(BOSS),"Exact native Boss owner required");List<MethodNode> methods=owner.methods.stream().filter(value->value.name.equals(name)&&value.desc.equals(DESC)).toList();require(methods.size()==1,"Exact single native beam/combo graph required");return methods.getFirst();}
    private static List<AbstractInsnNode> code(Iterable<AbstractInsnNode> instructions){List<AbstractInsnNode> result=new ArrayList<>();for(AbstractInsnNode instruction:instructions)if(instruction.getOpcode()>=0)result.add(instruction);return result;}
    private static MethodInsnNode one(MethodNode method,String owner,String name,String descriptor){List<MethodInsnNode> calls=new ArrayList<>();for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode member&&member.owner.equals(owner)&&member.name.equals(name)&&member.desc.equals(descriptor))calls.add(member);require(calls.size()==1,"Exact beam/combo graph call inventory: "+owner+"."+name);return calls.getFirst();}
    private static AbstractInsnNode previous(AbstractInsnNode instruction){AbstractInsnNode result=instruction.getPrevious();while(result!=null&&result.getOpcode()<0)result=result.getPrevious();return result;}
    private static boolean equal(AbstractInsnNode left,AbstractInsnNode right){if(left==null||left.getOpcode()!=right.getOpcode())return false;if(left instanceof VarInsnNode value&&right instanceof VarInsnNode wanted)return value.var==wanted.var;if(left instanceof LdcInsnNode value&&right instanceof LdcInsnNode wanted)return Objects.equals(value.cst,wanted.cst);if(left instanceof FieldInsnNode value&&right instanceof FieldInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc);if(left instanceof MethodInsnNode value&&right instanceof MethodInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc)&&value.itf==wanted.itf;return left instanceof InsnNode&&right instanceof InsnNode;}
    private static InsnList extendedRay(){InsnList result=new InsnList();result.add(new VarInsnNode(ASTORE,15));result.add(new InsnNode(DUP));result.add(new VarInsnNode(ALOAD,15));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"util/XuanlanLengths","extend","(Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;)Lnet/minecraft/world/phys/Vec3;",false));return result;}
    private static InsnList comboAction(){InsnList result=new InsnList();result.add(new VarInsnNode(ALOAD,0));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"body/BodySignals","combo","(L"+BOSS+";)V",false));return result;}
    private static void removeThrough(MethodNode method,AbstractInsnNode last,InsnList expected){List<AbstractInsnNode> wanted=code(expected);List<AbstractInsnNode> removed=new ArrayList<>();AbstractInsnNode cursor=last;for(int index=wanted.size()-1;index>=0;index--){require(equal(cursor,wanted.get(index)),"Exact original beam/combo hook operands/ordering differ");removed.add(cursor);cursor=previous(cursor);}for(AbstractInsnNode instruction:removed)method.instructions.remove(instruction);}
    public static void install(ClassNode owner){for(String name:new TreeSet<>(PREIMAGES.keySet())){MethodNode method=method(owner,name);if(!NativeBossLivingComposerSupportV2.methodFingerprint(method).equals(PREIMAGES.get(name))){verify(method);continue;}if(name.equals("beamStrike")){require(method.maxLocals<=15,"Exact unused scratch slot15 in accepted NF beam preimage");MethodInsnNode clip=one(method,BOSS,"clipSkillRay","(Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;)Lnet/minecraft/world/phys/Vec3;");require(clip.getOpcode()==INVOKEVIRTUAL,"Exact virtual native clipping anchor");method.instructions.insertBefore(clip,extendedRay());method.maxLocals=16;}else{MethodInsnNode beam=one(method,BOSS,"beamStrike",DESC);require(beam.getOpcode()==INVOKEVIRTUAL,"Exact native combination release anchor");method.instructions.insert(beam,comboAction());}method.maxStack=Math.max(method.maxStack,5);verify(method);}}
    private static void verify(MethodNode source){MethodNode restored=NativeBossLivingComposerSupportV2.copy(source);if(source.name.equals("beamStrike"))removeThrough(restored,one(restored,ROOT+"util/XuanlanLengths","extend","(Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;)Lnet/minecraft/world/phys/Vec3;"),extendedRay());else removeThrough(restored,one(restored,ROOT+"body/BodySignals","combo","(L"+BOSS+";)V"),comboAction());require(NativeBossLivingComposerSupportV2.methodFingerprint(restored).equals(PREIMAGES.get(source.name)),"Whole accepted NF beam/combo graph changed outside exact original callback addition: "+source.name);}
    public static void verifyInstalled(ClassNode owner){for(String name:PREIMAGES.keySet())verify(method(owner,name));}
}
